   228      if (type == Elf64_Ehdr::ET_EXEC) {
   229          // check for Linux kernels
   230          upx_uint64_t const entry = get_te64(&ehdr->e_entry);
   231          if (entry == 0xC0100000)    // uncompressed vmlinux
   232              return 1000;
   233          if (entry == 0x00001000)    // compressed vmlinux
   234              return 1001;
   235          if (entry == 0x00100000)    // compressed bvmlinux
   236              return 1002;
   237      }
   238
   239      // FIXME: add more checks for kernels
   240
   241      // FIXME: add special checks for other ELF i386 formats, like
   242      //        NetBSD, OpenBSD, Solaris, ....
   243
   244      // success
   245      return 0;
