  8618  unsigned PackLinuxElf::gnu_hash(char const *q)
  8619  {
  8620      unsigned char const *p = (unsigned char const *)q;
  8621      unsigned h;
  8622
  8623      for (h= 5381; 0!=*p; ++p) {
  8624          h += *p + (h << 5);
  8625      }
  8626      return h;
  8627  }
  8628
  8629  unsigned PackLinuxElf::elf_hash(char const *p)
  8630  {
  8631      unsigned h;
  8632      for (h= 0; 0!=*p; ++p) {
  8633          h = *p + (h<<4);
  8634          {
  8635              unsigned const t = 0xf0000000u & h;
  8636              h &= ~t;
  8637              h ^= t>>24;
  8638          }
  8639      }
  8640      return h;
  8641  }
