  8258  upx_uint64_t
  8259  PackLinuxElf64::elf_get_offset_from_address(upx_uint64_t addr) const
  8260  {
  8261      Elf64_Phdr const *phdr = phdri;
  8262      int j = e_phnum;
  8263      for (; --j>=0; ++phdr) if (is_LOAD(phdr)) {
  8264          upx_uint64_t const t = addr - get_te64(&phdr->p_vaddr);
  8265          if (t < get_te64(&phdr->p_filesz)) {
  8266              upx_uint64_t const p_offset = get_te64(&phdr->p_offset);
  8267              if (file_size_u <= p_offset) { // FIXME: weak
  8268                  char msg[40]; snprintf(msg, sizeof(msg),
  8269                      "bad Elf64_Phdr[%d].p_offset %#lx",
  8270                      -1+ e_phnum - j, (long unsigned)p_offset);
  8271                  throwCantPack(msg);
  8272              }
  8273              return t + p_offset;
  8274          }
  8275      }
  8276      return 0;
  8277  }
