  8279  u64_t  // returns .p_offset
  8280  PackLinuxElf64::check_pt_load(Elf64_Phdr const *const phdr)
  8281  {
  8282      u64_t filesz = get_te64(&phdr->p_filesz);
  8283      u64_t offset = get_te64(&phdr->p_offset), offend = filesz + offset;
  8284      u64_t vaddr  = get_te64(&phdr->p_vaddr);
  8285      u64_t paddr  = get_te64(&phdr->p_paddr);
  8286      u64_t align  = get_te64(&phdr->p_align);
  8287
  8288      if ((-1+ align) & (paddr ^ vaddr)
  8289      ||  file_size_u <= (u64_t)offset
  8290      ||  file_size_u <  (u64_t)offend
  8291      ||  file_size_u <  (u64_t)filesz) {
  8292          char msg[50]; snprintf(msg, sizeof(msg), "bad PT_LOAD phdr[%u]",
  8293              (unsigned)(phdr - phdri));
  8294          throwCantPack(msg);
  8295      }
  8296      return offset;
  8297  }
